    flash: {"q":"Quelles couleurs sont autorisées à Tavel et à Lirac ?","a":"Tavel : uniquement le rosé. Lirac : rouge, rosé et blanc.","keys":[["tavel"],["rosé","rose"],["lirac"],["rouge"]]},
